/* ===== PrismU – colorful course registration ===== */
:root {
  --purple: #6c5ce7;
  --blue: #0984e3;
  --teal: #00b894;
  --pink: #e84393;
  --orange: #e17055;
  --yellow: #fdcb6e;
  --red: #d63031;
  --ink: #2d3436;
  --muted: #636e72;
  --bg: #f6f4ff;
  --card: #ffffff;
  --line: #e6e3f5;
  --radius: 16px;
  --shadow: 0 10px 30px rgba(108, 92, 231, 0.12);
  --rainbow: linear-gradient(90deg, #6c5ce7, #0984e3, #00b894, #fdcb6e, #e17055, #e84393);
}

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background:
    radial-gradient(circle at 10% 0%, rgba(232, 67, 147, 0.08), transparent 40%),
    radial-gradient(circle at 90% 30%, rgba(9, 132, 227, 0.08), transparent 40%),
    var(--bg);
  line-height: 1.55;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
main { flex: 1; }
h1, h2, h3 { line-height: 1.2; margin: 0 0 .5em; }
a { color: var(--purple); }
img { max-width: 100%; }

.container { width: min(1200px, 100% - 2.5rem); margin-inline: auto; }
.section { margin-top: 3rem; }
.muted { color: var(--muted); }
.text-danger { color: var(--red); }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip-link {
  position: absolute; left: 1rem; top: -3rem; z-index: 100;
  background: var(--ink); color: #fff; padding: .5rem 1rem; border-radius: 8px;
}
.skip-link:focus { top: 1rem; }
:focus-visible { outline: 3px solid var(--yellow); outline-offset: 2px; }

/* ===== Navbar ===== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: linear-gradient(90deg, #6c5ce7 0%, #a259ff 35%, #e84393 70%, #fd79a8 100%);
  box-shadow: 0 4px 20px rgba(108, 92, 231, .35);
}
.site-header::after { content: ""; display: block; height: 4px; background: var(--rainbow); }
.navbar {
  width: min(1200px, 100% - 2.5rem); margin-inline: auto;
  display: flex; align-items: center; justify-content: space-between;
  min-height: 64px; position: relative;
}
.brand {
  display: flex; align-items: center; gap: .5rem;
  color: #fff; text-decoration: none; font-size: 1.4rem; letter-spacing: .5px;
}
.brand strong { color: var(--yellow); }
.brand-logo {
  display: grid; place-items: center; width: 40px; height: 40px;
  background: rgba(255,255,255,.2); border-radius: 12px;
}
.nav-links { list-style: none; display: flex; gap: .35rem; margin: 0; padding: 0; }
.nav-links a {
  display: flex; align-items: center; gap: .4rem;
  color: #fff; text-decoration: none; font-weight: 600;
  padding: .55rem 1rem; border-radius: 999px; transition: background .2s;
}
.nav-links a:hover { background: rgba(255,255,255,.18); }
.nav-links a.active { background: #fff; color: var(--purple); }
.nav-badge {
  background: var(--yellow); color: var(--ink); font-size: .75rem;
  min-width: 1.4rem; height: 1.4rem; border-radius: 999px;
  display: inline-grid; place-items: center; padding: 0 .35rem;
}
.nav-badge[hidden] { display: none; }
.nav-toggle {
  display: none; background: rgba(255,255,255,.2); border: 0; border-radius: 10px;
  width: 44px; height: 44px; cursor: pointer; padding: 10px;
  flex-direction: column; justify-content: space-between;
}
.nav-toggle span { display: block; height: 3px; background: #fff; border-radius: 3px; transition: transform .25s, opacity .25s; }
.nav-toggle[aria-expanded="true"] span:nth-child(1) { transform: translateY(9.5px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] span:nth-child(2) { opacity: 0; }
.nav-toggle[aria-expanded="true"] span:nth-child(3) { transform: translateY(-9.5px) rotate(-45deg); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: .4rem;
  border: 0; border-radius: 999px; padding: .7rem 1.4rem;
  font: inherit; font-weight: 700; cursor: pointer; text-decoration: none;
  transition: transform .15s, box-shadow .2s, filter .2s; white-space: nowrap;
}
.btn:hover { transform: translateY(-2px); filter: brightness(1.05); }
.btn:active { transform: translateY(0); }
.btn-sm { padding: .45rem 1rem; font-size: .9rem; }
.btn-lg { padding: .9rem 1.8rem; font-size: 1.05rem; }
.btn-block { width: 100%; }
.btn-primary { background: linear-gradient(135deg, #6c5ce7, #e84393); color: #fff; box-shadow: 0 6px 16px rgba(232, 67, 147, .35); }
.btn-secondary { background: linear-gradient(135deg, #0984e3, #00cec9); color: #fff; box-shadow: 0 6px 16px rgba(9, 132, 227, .3); }
.btn-success { background: linear-gradient(135deg, #00b894, #55efc4); color: #fff; }
.btn-danger { background: linear-gradient(135deg, #d63031, #e17055); color: #fff; box-shadow: 0 6px 16px rgba(214, 48, 49, .25); }
.btn-ghost { background: #efeafd; color: var(--purple); }
.btn-light { background: #fff; color: var(--purple); }
.btn-outline-light { background: transparent; color: #fff; box-shadow: inset 0 0 0 2px #fff; }
.btn-disabled { background: #dfe6e9; color: var(--muted); }
.btn.is-static { cursor: default; }
.btn.is-static:hover { transform: none; filter: none; }

/* ===== Hero ===== */
.hero {
  position: relative; overflow: hidden; color: #fff;
  background: linear-gradient(135deg, #6c5ce7 0%, #0984e3 45%, #00b894 100%);
  padding: 4.5rem 0 6rem;
  display: grid; grid-template-columns: 1.3fr 1fr; align-items: center;
  padding-inline: max(1.25rem, (100% - 1200px) / 2);
}
.hero::before {
  content: ""; position: absolute; inset: auto -10% -60% auto; width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(253, 203, 110, .45), transparent 60%);
}
.hero-content { position: relative; z-index: 1; }
.eyebrow {
  display: inline-block; background: rgba(255,255,255,.2); padding: .35rem .9rem;
  border-radius: 999px; font-weight: 600; font-size: .9rem; margin: 0 0 1rem;
}
.hero h1 { font-size: clamp(2rem, 4.5vw, 3.2rem); }
.gradient-text {
  background: linear-gradient(90deg, #ffeaa7, #fd79a8, #ffeaa7);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.lead { font-size: 1.15rem; opacity: .95; max-width: 34rem; }
.hero-search {
  display: flex; gap: .5rem; background: #fff; padding: .4rem; border-radius: 999px;
  max-width: 34rem; margin: 1.5rem 0 1rem; box-shadow: 0 10px 30px rgba(0,0,0,.15);
}
.hero-search input { flex: 1; border: 0; padding: .6rem 1rem; font: inherit; border-radius: 999px; min-width: 0; }
.hero-search input:focus { outline: none; }
.hero-actions { display: flex; flex-wrap: wrap; gap: .75rem; }
.hero-art { position: relative; height: 320px; }
.blob {
  position: absolute; display: grid; place-items: center; font-size: 3rem;
  width: 120px; height: 120px; border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
  box-shadow: 0 15px 35px rgba(0,0,0,.2); animation: float 6s ease-in-out infinite;
}
.b1 { background: #fdcb6e; top: 10%; left: 15%; }
.b2 { background: #fd79a8; top: 5%; right: 10%; animation-delay: -1.5s; width: 100px; height: 100px; }
.b3 { background: #55efc4; bottom: 10%; left: 30%; animation-delay: -3s; }
.b4 { background: #a29bfe; bottom: 20%; right: 5%; animation-delay: -4.5s; width: 105px; height: 105px; }
@keyframes float { 0%, 100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-18px) rotate(6deg); } }
@media (prefers-reduced-motion: reduce) { .blob { animation: none; } html { scroll-behavior: auto; } }

/* ===== Stats ===== */
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.hero + .container .stats-grid { margin-top: -3rem; position: relative; z-index: 2; }
.stat {
  border-radius: var(--radius); padding: 1.25rem; color: #fff; box-shadow: var(--shadow);
  display: flex; flex-direction: column;
}
.stat strong { font-size: 1.9rem; line-height: 1.1; }
.stat span { opacity: .95; font-weight: 600; }
.stat-1 { background: linear-gradient(135deg, #6c5ce7, #a29bfe); }
.stat-2 { background: linear-gradient(135deg, #0984e3, #74b9ff); }
.stat-3 { background: linear-gradient(135deg, #00b894, #55efc4); }
.stat-4 { background: linear-gradient(135deg, #e84393, #fdcb6e); }

/* ===== Sections ===== */
.section-title { font-size: 1.7rem; position: relative; padding-bottom: .4rem; display: inline-block; }
.section-title::after { content: ""; position: absolute; left: 0; bottom: 0; width: 60%; height: 4px; border-radius: 4px; background: var(--rainbow); }
.section-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: .75rem; margin-bottom: 1rem; }
.section-head .section-title, .section-head h2 { margin-bottom: 0; }
.link-arrow { font-weight: 700; text-decoration: none; color: var(--pink); }

.dept-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 1rem; margin-top: 1rem; }
.dept-tile {
  display: flex; flex-direction: column; gap: .2rem; padding: 1.25rem; text-decoration: none;
  color: #fff; border-radius: var(--radius);
  background: linear-gradient(135deg, var(--accent), color-mix(in srgb, var(--accent) 55%, #fff));
  box-shadow: 0 8px 20px color-mix(in srgb, var(--accent) 35%, transparent);
  transition: transform .2s;
}
.dept-tile:hover { transform: translateY(-4px) scale(1.02); }
.dept-tile span { font-size: .9rem; opacity: .95; }

.steps { list-style: none; padding: 0; margin: 1rem 0 0; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.step { background: var(--card); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); border-top: 6px solid var(--c); }
.step > span {
  display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%;
  background: var(--c); color: #fff; font-weight: 800; margin-bottom: .75rem;
}
.step p { margin: 0; color: var(--muted); }
.step-1 { --c: var(--purple); } .step-2 { --c: var(--pink); } .step-3 { --c: var(--teal); }

/* ===== Page banners ===== */
.page-banner { color: #fff; padding: 2.75rem 0; margin-bottom: 2rem; position: relative; overflow: hidden; }
.page-banner h1 { font-size: clamp(1.8rem, 4vw, 2.6rem); margin-bottom: .25rem; }
.page-banner p { margin: 0; font-size: 1.1rem; opacity: .95; }
.page-banner::after {
  content: ""; position: absolute; right: -60px; top: -80px; width: 260px; height: 260px;
  border-radius: 50%; background: rgba(255,255,255,.15);
}
.banner-catalog { background: linear-gradient(120deg, #0984e3, #6c5ce7 60%, #e84393); }
.banner-register { background: linear-gradient(120deg, #e84393, #e17055 55%, #fdcb6e); }
.banner-profile { background: linear-gradient(120deg, #00b894, #00cec9 50%, #0984e3); }

/* ===== Forms ===== */
.field { display: flex; flex-direction: column; gap: .35rem; min-width: 0; }
.field label { font-weight: 700; font-size: .9rem; color: #4b4b6b; }
input[type="text"], input[type="email"], input[type="search"], select, textarea {
  font: inherit; color: var(--ink); width: 100%;
  padding: .65rem .85rem; border: 2px solid var(--line); border-radius: 12px; background: #fff;
  transition: border-color .2s, box-shadow .2s;
}
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--purple); box-shadow: 0 0 0 4px rgba(108, 92, 231, .15); }
input[readonly] { background: #f4f2fc; color: var(--muted); }
textarea { resize: vertical; }
.checkbox { display: flex; gap: .6rem; align-items: flex-start; cursor: pointer; margin-top: 1rem; }
.checkbox input { width: 20px; height: 20px; accent-color: var(--pink); margin-top: .15rem; flex-shrink: 0; }

/* ===== Catalog toolbar ===== */
.toolbar {
  display: grid; gap: 1rem; grid-template-columns: repeat(4, 1fr);
  background: var(--card); padding: 1.25rem; border-radius: var(--radius); box-shadow: var(--shadow);
  border-left: 6px solid transparent; border-image: linear-gradient(#6c5ce7, #e84393, #fdcb6e) 1;
}
.field-search { grid-column: span 2; }
.field-btn { justify-content: flex-end; }
.result-count { font-weight: 700; color: var(--purple); margin: 1.5rem 0 1rem; }

/* ===== Course cards ===== */
.course-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1.25rem; margin-top: 1rem; }
.course-card {
  background: var(--card); border-radius: var(--radius); padding: 1.25rem;
  box-shadow: var(--shadow); display: flex; flex-direction: column; gap: .6rem;
  border-top: 6px solid var(--accent); position: relative; overflow: hidden;
  transition: transform .2s, box-shadow .2s;
}
.course-card::before {
  content: ""; position: absolute; top: -40px; right: -40px; width: 120px; height: 120px; border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 14%, transparent);
}
.course-card:hover { transform: translateY(-5px); box-shadow: 0 16px 36px color-mix(in srgb, var(--accent) 30%, transparent); }
.card-top { display: flex; justify-content: space-between; align-items: center; gap: .5rem; position: relative; }
.course-code {
  font-weight: 800; color: var(--accent, var(--purple)); letter-spacing: .5px;
  background: color-mix(in srgb, var(--accent, var(--purple)) 12%, #fff); padding: .2rem .6rem; border-radius: 8px;
}
.chip { font-size: .78rem; font-weight: 700; color: #fff; background: var(--accent); padding: .2rem .65rem; border-radius: 999px; }
.course-card h3 { margin: 0; font-size: 1.2rem; }
.card-desc { margin: 0; color: var(--muted); font-size: .93rem; flex: 1; }
.card-meta { list-style: none; padding: 0; margin: 0; display: grid; gap: .2rem; font-size: .9rem; }
.seat-bar { height: 8px; background: #eeeaf9; border-radius: 99px; overflow: hidden; }
.seat-fill { height: 100%; background: linear-gradient(90deg, #00b894, #55efc4); border-radius: 99px; }
.seat-fill.almost { background: linear-gradient(90deg, #fdcb6e, #e17055); }
.seat-fill.full { background: linear-gradient(90deg, #d63031, #e84393); }
.card-bottom { display: flex; justify-content: space-between; align-items: center; gap: .5rem; }
.seats { font-weight: 700; font-size: .9rem; }

.empty-state { grid-column: 1 / -1; text-align: center; padding: 3rem 1rem; color: var(--muted); }
.empty-state > span { font-size: 3rem; display: block; }
.empty-state h3 { color: var(--ink); margin-top: .5rem; }

/* ===== Cards & register ===== */
.card { background: var(--card); border-radius: var(--radius); padding: 1.5rem; box-shadow: var(--shadow); }
.register-layout { display: grid; grid-template-columns: 1fr 340px; gap: 1.5rem; align-items: start; }
fieldset { border: 0; padding: 0; margin: 0 0 1.75rem; }
legend { font-size: 1.2rem; font-weight: 800; display: flex; align-items: center; gap: .6rem; margin-bottom: 1rem; }
.legend-num { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; color: #fff; font-size: 1rem; }
.n1 { background: var(--purple); } .n2 { background: var(--pink); } .n3 { background: var(--orange); }
.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
.field-wide { grid-column: 1 / -1; }
.form-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: .75rem; }
.form-errors {
  background: #ffeaea; border: 2px solid #ff7675; color: #a81e1e; border-radius: 12px;
  padding: 1rem 1.25rem; margin-bottom: 1.5rem;
}
.form-errors ul { margin: .4rem 0 0; padding-left: 1.2rem; }
.course-preview {
  margin-top: 1rem; padding: 1.25rem; border-radius: 14px;
  border: 2px dashed color-mix(in srgb, var(--accent, #b2bec3) 60%, #fff);
  background: color-mix(in srgb, var(--accent, #b2bec3) 7%, #fff);
}
.course-preview h3 { margin: .6rem 0 .3rem; }
.course-preview p { margin: 0 0 .75rem; }
.warn { color: #b35400; font-weight: 700; margin: .75rem 0 0 !important; }
.detail-list { display: grid; grid-template-columns: max-content 1fr; gap: .4rem 1rem; margin: 0; }
.detail-list dt { font-weight: 700; color: var(--muted); }
.detail-list dd { margin: 0; word-break: break-word; }

.summary-card { position: sticky; top: 90px; border-top: 6px solid var(--teal); }
.summary-row { display: flex; justify-content: space-between; padding: .4rem 0; }
.summary-row strong { color: var(--purple); }
.credit-bar { height: 12px; background: #eeeaf9; border-radius: 99px; overflow: hidden; margin: .4rem 0 1rem; }
.credit-fill { height: 100%; width: 0; background: var(--rainbow); border-radius: 99px; transition: width .5s; }
.summary-list { list-style: none; padding: 0; margin: 0 0 1.25rem; display: grid; gap: .5rem; }
.summary-list li:not(.muted) {
  display: flex; gap: .5rem; align-items: center; padding: .55rem .75rem; border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 10%, #fff); border-left: 4px solid var(--accent); font-size: .92rem;
}
.summary-list li span { margin-left: auto; font-weight: 700; color: var(--accent); white-space: nowrap; }

/* ===== Profile ===== */
.profile-layout { display: grid; grid-template-columns: 320px 1fr; gap: 1.5rem; align-items: start; }
.profile-card { text-align: center; border-top: 6px solid var(--pink); }
.profile-card .detail-list { text-align: left; margin: 1.25rem 0; }
.avatar {
  width: 96px; height: 96px; border-radius: 50%; margin: 0 auto 1rem;
  display: grid; place-items: center; font-size: 2rem; font-weight: 800; color: #fff;
  background: conic-gradient(from 0deg, #6c5ce7, #0984e3, #00b894, #fdcb6e, #e17055, #e84393, #6c5ce7);
  box-shadow: 0 0 0 6px #fff, 0 0 0 9px #efeafd;
}
.profile-card h2 { margin-bottom: .1rem; }
.edit-form { display: grid; gap: .75rem; text-align: left; margin: 1.25rem 0; }
.edit-form[hidden], .detail-list[hidden], .btn[hidden] { display: none; }
.profile-main { display: grid; gap: 1.5rem; min-width: 0; }
.profile-main .stat strong { font-size: 1.5rem; }
.table-card { border-top: 6px solid var(--blue); }
.table-actions { display: flex; gap: .5rem; flex-wrap: wrap; }
.table-wrap { overflow-x: auto; }
.data-table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: .95rem; }
.data-table[hidden] { display: none; }
.data-table th {
  text-align: left; padding: .8rem; color: #fff; white-space: nowrap;
  background: linear-gradient(90deg, #6c5ce7, #0984e3);
}
.data-table thead th:nth-child(n+4) { background: linear-gradient(90deg, #0984e3, #00b894); }
.data-table thead th:nth-child(n+7) { background: linear-gradient(90deg, #00b894, #00cec9); }
.data-table thead th:first-child { border-top-left-radius: 12px; }
.data-table thead th:last-child { border-top-right-radius: 12px; }
.data-table th[data-sort] { cursor: pointer; user-select: none; }
.data-table th[data-sort]::after { content: " ↕"; opacity: .6; }
.data-table th[aria-sort="ascending"]::after { content: " ↑"; opacity: 1; }
.data-table th[aria-sort="descending"]::after { content: " ↓"; opacity: 1; }
.data-table td { padding: .8rem; border-bottom: 1px solid var(--line); vertical-align: middle; }
.data-table tbody tr:nth-child(even) { background: #faf8ff; }
.data-table tbody tr:hover { background: #f1edff; }
.data-table tfoot td { font-weight: 800; background: #fff6e0; color: #8a5a00; }
.data-table small { color: var(--muted); }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: .45rem; }

/* ===== Modal ===== */
.modal-overlay {
  position: fixed; inset: 0; z-index: 200; display: grid; place-items: center; padding: 1rem;
  background: rgba(45, 52, 54, .55); backdrop-filter: blur(4px);
  opacity: 0; transition: opacity .2s;
}
.modal-overlay[hidden] { display: none; }
.modal-overlay.show { opacity: 1; }
.modal {
  position: relative; background: #fff; border-radius: 22px; padding: 2rem 1.75rem 1.5rem;
  width: min(520px, 100%); max-height: calc(100vh - 2rem); overflow-y: auto;
  box-shadow: 0 30px 60px rgba(0,0,0,.25); text-align: center;
  border-top: 8px solid transparent; border-image: var(--rainbow) 1;
  transform: translateY(20px) scale(.97); transition: transform .25s;
}
.modal-overlay.show .modal { transform: none; }
.modal .detail-list { text-align: left; background: #f8f6ff; padding: 1rem; border-radius: 12px; margin: 1rem 0 0; }
.modal-close {
  position: absolute; top: .75rem; right: .75rem; width: 36px; height: 36px; border: 0; border-radius: 50%;
  background: #f1edff; color: var(--purple); font-size: 1.4rem; cursor: pointer; line-height: 1;
}
.modal-icon {
  width: 64px; height: 64px; margin: 0 auto 1rem; border-radius: 50%;
  display: grid; place-items: center; font-size: 1.8rem;
