.modal-icon.primary { background: linear-gradient(135deg, #a29bfe, #fd79a8); }
.modal-icon.success { background: linear-gradient(135deg, #55efc4, #81ecec); }
.modal-icon.danger { background: linear-gradient(135deg, #ff7675, #fab1a0); }
.modal-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: .75rem; margin-top: 1.5rem; }
.modal-actions .btn[hidden] { display: none; }

/* ===== Toast ===== */
.toast {
