const { JSDOM, VirtualConsole } = require('jsdom');
const fs = require('fs');
const errors = [];
const store = {};
function open(file, query = '') {
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => errors.push(file + ': ' + e.message));
  vc.on('error', e => errors.push(file + ' console.error: ' + e));
  const html = fs.readFileSync('/work/' + file, 'utf8').replace(/<script src="(.+?)"><\/script>/g, (m, s) => `<script>${fs.readFileSync('/work/' + s, 'utf8')}</script>`);
  const dom = new JSDOM(html, { url: 'http://localhost/' + file + query, runScripts: 'dangerously', virtualConsole: vc, pretendToBeVisual: true,
    beforeParse(w) { Object.keys(store).forEach(k => w.localStorage.setItem(k, store[k])); w.HTMLElement.prototype.scrollIntoView = () => {}; } });
  const w = dom.window;
  w.document.dispatchEvent(new w.Event('DOMContentLoaded'));
  return w;
}
function persist(w) { for (let i = 0; i < w.localStorage.length; i++) { const k = w.localStorage.key(i); store[k] = w.localStorage.getItem(k); } }
const $ = (w, s) => w.document.querySelector(s);
const change = (w, el) => el.dispatchEvent(new w.Event('change'));
(async () => {
  // home
  let w = open('index.html');
  // DOMContentLoaded fires twice possibly (jsdom fires naturally too) - check duplicates
  console.log('home stats', $(w,'#home-stats').children.length, 'depts', $(w,'#home-depts').children.length, 'featured', $(w,'#featured-courses').children.length);
