  $(w,'#filter-availability').value = 'open'; change(w, $(w,'#filter-availability')); console.log('CS open', $(w,'#result-count').textContent);
  $(w,'#clear-filters').click(); console.log('cleared', $(w,'#result-count').textContent);
  s.value = 'zzz'; s.dispatchEvent(new w.Event('input')); console.log('none', !!$(w,'.empty-state'));
  // register
  w = open('register.html', '?course=CS101');
  console.log('preselected', $(w,'#reg-course').value);
  const form = $(w,'#register-form');
  form.dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('errors shown', !$(w,'#form-errors').hidden, $(w,'#form-errors').textContent.includes('policy'));
  $(w,'#reg-agree').checked = true; form.dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('modal open', !$(w,'#modal').hidden, $(w,'#modal-title').textContent);
  $(w,'#modal-confirm').click(); await new Promise(r => setTimeout(r, 100));
  console.log('success', $(w,'#modal-title').textContent, 'badge', $(w,'#nav-badge').textContent, 'summary', $(w,'#summary-credits').textContent);
  $(w,'#modal-cancel').click();
  $(w,'#reg-course').value = 'PSY101'; change(w, $(w,'#reg-course'));
  console.log('preview warn', !!$(w,'#course-preview .warn'));
  $(w,'#reg-agree').checked = true; form.dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('conflict err', $(w,'#form-errors').textContent.includes('conflicts'));
  $(w,'#reg-course').value = 'CS340'; change(w, $(w,'#reg-course')); form.dispatchEvent(new w.Event('submit', { cancelable: true }));
  $(w,'#modal-confirm').click(); await new Promise(r => setTimeout(r, 100));
  $(w,'#reg-course').value = 'CS220'; $(w,'#reg-agree').checked = true; form.dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('full err', $(w,'#form-errors').textContent.includes('full'));
  persist(w);
  // profile
  w = open('profile.html');
  console.log('rows', w.document.querySelectorAll('#reg-table tbody tr').length, 'total', $(w,'#table-total').textContent, 'empty hidden', $(w,'#table-empty').hidden);
  w.document.querySelector('th[data-sort=credits]').click();
  console.log('sorted first', $(w,'#reg-table tbody tr td').textContent.trim());
  $(w,'[data-drop=CS340]').click(); $(w,'#modal-confirm').click();
  console.log('after drop', w.document.querySelectorAll('#reg-table tbody tr').length);
  $(w,'#edit-btn').click(); $(w,'#edit-first').value = 'Alex'; $(w,'#edit-form').dispatchEvent(new w.Event('submit', { cancelable: true }));
  console.log('name', $(w,'#profile-name').textContent, 'avatar', $(w,'#avatar').textContent);
  $(w,'#drop-all').click(); $(w,'#modal-confirm').click();
  console.log('empty shown', !$(w,'#table-empty').hidden, 'table hidden', $(w,'#reg-table').hidden);
  $(w,'.nav-toggle').click(); console.log('menu open', $(w,'.nav-links').classList.contains('open'));
  console.log('ERRORS', errors);
})();
